    print(f"Index {i}: '{inp}' -> '{outp}'")
    print(f"  Length: {len(inp)} -> {len(outp)}")
    if len(inp) != len(outp):
        if len(outp) > len(inp):
            print(f"  Append: '{outp[len(inp):]}'")
        else:
            print(f"  Truncate to {len(outp)} chars")

print("\nCharacter-by-character comparison:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Index {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
